// Regression harness for lib/server/cli-jsonl.ts —— CLI jsonl 的 turn 归属。
//
// 这个文件存在的理由是一次真实漂移：cli-import（jsonl → 节点树）和 cli-fork
// （在某个 turn 上截前缀造分叉）各抄了一份 turn-start 判据，import 那份后来长出
// 5 道结构闸，fork 那份没跟。两边对「turn 从哪开始」的答案分家后，fork 的入参
// turnUuid 恰恰是 import 定的节点 id —— 等于在一条自己认不出的 turn 上截前缀。
//
// 2026-08-01 合并前实测（889 个 jsonl / 1897 个有回答的 turn）：
//   36 个 turn（1.90%）fork 侧找不到 tail   → 分叉静默降级成线性
//   315 个 turn（16.61%）选出的 tail 与 import 归属不符 → 前缀截在没说完的回答中间
// 合并后两项均为 0。本 harness 就是防它再分家 —— 判据不能只靠注释约定。
//
// Run:  bun scripts/test-cli-jsonl.ts

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import {
  type CliRawEntry,
  indexByUuid,
  isTurnStart,
  looseTurnStart,
  makeTurnOwnership,
  readJsonlLines,
  terminalAssistantLine,
  userText,
} from "@/lib/server/cli-jsonl";
import { parseCliSessionJsonl } from "@/lib/server/cli-import";

let failures = 0;
function check(label: string, ok: boolean, got?: unknown) {
  if (ok) console.log(`  ✓ ${label}`);
  else {
    failures++;
    console.log(
      `  ✗ ${label}${got === undefined ? "" : ` — got ${JSON.stringify(got)}`}`,
    );
  }
}

function section(name: string) {
  console.log(`\n── ${name}`);
}

// ── 合成语料工具 ────────────────────────────────────────────────────────────

let seq = 0;
function uid(tag: string): string {
  seq++;
  return `${tag}-${String(seq).padStart(4, "0")}`;
}

function user(
  uuid: string,
  parentUuid: string | null,
  text: string,
  extra: Partial<CliRawEntry> = {},
): CliRawEntry {
  return {
    type: "user",
    uuid,
    parentUuid,
    timestamp: "2026-08-01T00:00:00.000Z",
    message: { role: "user", content: [{ type: "text", text }] },
    ...extra,
  };
}

function assistant(
  uuid: string,
  parentUuid: string | null,
  text: string,
  extra: Partial<CliRawEntry> = {},
): CliRawEntry {
  return {
    type: "assistant",
    uuid,
    parentUuid,
    timestamp: "2026-08-01T00:00:01.000Z",
    message: { role: "assistant", content: [{ type: "text", text }] },
    ...extra,
  };
}

function writeFixture(entries: CliRawEntry[]): string {
  const dir = path.join(os.tmpdir(), "trellis-cli-jsonl-test");
  fs.mkdirSync(dir, { recursive: true });
  const p = path.join(dir, `${uid("fx")}.jsonl`);
  fs.writeFileSync(p, entries.map((e) => JSON.stringify(e)).join("\n") + "\n");
  return p;
}

// ── 1. turn-start 的结构闸 ──────────────────────────────────────────────────
// 每道闸各一条：CLI 注入的假提问必须被挡下。挡漏任何一道，后续 assistant 的最终
// 回复就会被劫走挂到假 turn 上（真 turn 只剩工具调用、response 为空）。
{
  section("turn-start 的结构闸");
  check("真用户提问认得出", isTurnStart(user(uid("u"), null, "帮我看下这个报错")));

  const gates: [string, Partial<CliRawEntry>][] = [
    ["isMeta", { isMeta: true }],
    ["promptSource=system", { promptSource: "system" }],
    ["interruptedMessageId", { interruptedMessageId: "abc" }],
    ["isCompactSummary", { isCompactSummary: true }],
    ["isVisibleInTranscriptOnly", { isVisibleInTranscriptOnly: true }],
  ];
  for (const [name, extra] of gates) {
    check(
      `${name} 挡下 CLI 注入`,
      !isTurnStart(user(uid("u"), null, "Continue from where you left off.", extra)),
    );
  }

  check(
    "命令噪声挡下（老版本 jsonl 兜底）",
    !isTurnStart(user(uid("u"), null, "<command-name>/clear</command-name>")),
  );
  check(
    "tool_result 不是 turn-start",
    !isTurnStart({
      type: "user",
      uuid: uid("u"),
      parentUuid: null,
      message: {
        role: "user",
        content: [{ type: "tool_result", tool_use_id: "t1", content: "ok" }],
      },
    }),
  );
  check("空文本不是 turn-start", !isTurnStart(user(uid("u"), null, "   ")));

  // 宽松判据必须恰好放行严格判据挡下的那些（兜底才有东西可认领），但不认 compact 摘要。
  check(
    "宽松判据放行 meta",
    looseTurnStart(user(uid("u"), null, "Continue…", { isMeta: true })),
  );
  check(
    "宽松判据不认 compact summary",
    !looseTurnStart(
      user(uid("u"), null, "Continue from where you left off.", {
        isCompactSummary: true,
      }),
    ),
  );
  check(
    "宽松判据不认 isVisibleInTranscriptOnly",
    !looseTurnStart(
      user(uid("u"), null, "Continue from where you left off.", {
        isVisibleInTranscriptOnly: true,
      }),
    ),
  );
  check(
    "宽松判据同样不认 tool_result",
    !looseTurnStart({
      type: "user",
      uuid: uid("u"),
      message: {
        role: "user",
        content: [{ type: "tool_result", tool_use_id: "t", content: "ok" }],
      },
    }),
  );
}

// ── 2. 历史 bug：假 turn-start 劫走真 turn 的回复 ───────────────────────────
{
  section("假 turn-start 不许劫走真 turn 的回复");

  const q = uid("q");
  const meta = uid("m");
  const a1 = uid("a");
  const a2 = uid("a");
  // 真提问 → CLI 注入的 meta（长得像提问）→ 两条 assistant。
  // 3 道闸的老判据会把 meta 当 turn-start，于是 a1/a2 全挂到 meta 上，
  // 真 turn q 的 tail 变成 null（分叉直接降级）。
  const entries = [
    user(q, null, "帮我把这个函数重构一下"),
    user(meta, q, "Base directory for this skill: /Users/x/.claude/skills/foo", {
      isMeta: true,
    }),
    assistant(a1, meta, "好的，我先读一下文件"),
    assistant(a2, a1, "重构完成，改了三处"),
  ];
  const p = writeFixture(entries);
  const rawLines = readJsonlLines(p)!;

  const tail = terminalAssistantLine(rawLines, q);
  check("真 turn 找得到 tail", tail !== null);
  check("tail 是最后一条 assistant", tail?.entry.uuid === a2, tail?.entry.uuid);

  const { resolveOwner } = makeTurnOwnership(indexByUuid(entries));
  check("两条 assistant 都归真 turn", resolveOwner(a1) === q && resolveOwner(a2) === q, {
    a1: resolveOwner(a1),
    a2: resolveOwner(a2),
  });

  // 同一份语料走 import：回复必须落在真 turn 上，不能出现空 response 的僵尸。
  const parsed = parseCliSessionJsonl(p);
  const turn = parsed?.turns.find((t) => t.id === q);
  check("import 也把回复归给真 turn", Boolean(turn?.response.includes("重构完成")), turn?.response);
  check("没有空 response 的僵尸 turn", (parsed?.turns ?? []).every((t) => t.response.trim() !== ""));
}

// ── 3. 宽松兜底：链头没有真提问时内容不许被丢 ───────────────────────────────
{
  section("宽松兜底承载 --continue / fork 出来的 jsonl");

  const meta = uid("m");
  const a1 = uid("a");
  // `claude --continue` 出来的 jsonl：链头就是 meta，严格判据下上溯不到任何
  // turn-start。没有兜底的话整段回复会被静默丢弃（实测 117 条消息 / 16030 字符）。
  const entries = [
    user(meta, null, "Continue from where you left off.", { isMeta: true }),
    assistant(a1, meta, "接着上次的进度，我继续处理剩下两个文件"),
  ];
  const p = writeFixture(entries);

  const { resolveOwner, fallbackStartIds } = makeTurnOwnership(indexByUuid(entries));
  check("兜底把 meta 认领成起点", resolveOwner(a1) === meta, resolveOwner(a1));
  check("认领记进 fallbackStartIds", fallbackStartIds.has(meta));

  const parsed = parseCliSessionJsonl(p);
  check("import 不丢这段回复", Boolean(parsed?.turns.some((t) => t.response.includes("继续处理"))));

  const rawLines = readJsonlLines(p)!;
  check("fork 也能在兜底 turn 上截前缀", terminalAssistantLine(rawLines, meta) !== null);
}

// ── 4. Compact Continuation：长动线上下文压缩后不丢最终回复且不断链 ─────────
{
  section("Compact Continuation 拓扑桥接与最终答复保留");

  const q1 = uid("q");
  const t1 = uid("a");
  const tr1 = uid("u");
  const sysCompact = uid("s");
  const compactSummary = uid("u");
  const att1 = uid("att");
  const aFinal = uid("a");
  const q2 = uid("q");
  const a2 = uid("a");

  // 场景：Turn 1 发起 -> 工具调用 -> 触发自动 Compact (system parent null + isCompactSummary)
  // -> Attachments -> 最终答复 aFinal -> Turn 2 发起 q2 -> 回答 a2
  const entries: CliRawEntry[] = [
    user(q1, null, "帮我分析全景车信与拓扑的过滤逻辑"),
    assistant(t1, q1, "", {
      message: {
        role: "assistant",
        content: [{ type: "tool_use", id: "call_1", name: "Read", input: {} }],
      },
    }),
    user(tr1, t1, "", {
      message: {
        role: "user",
        content: [{ type: "tool_result", tool_use_id: "call_1", content: "file content" }],
      },
    }),
    // Compact 块
    {
      type: "system",
      uuid: sysCompact,
      parentUuid: null,
      message: { role: "system", content: [] },
    },
    user(compactSummary, sysCompact, "This session is being continued from a previous conversation...", {
      isCompactSummary: true,
      isVisibleInTranscriptOnly: true,
    }),
    {
      type: "attachment",
      uuid: att1,
      parentUuid: compactSummary,
    },
    assistant(aFinal, att1, "在当前的架构中，路网车信数据主要分为两个层级..."),
    // 下一轮
    user(q2, aFinal, "所以是完全匹配才算挂上吗？"),
    assistant(a2, q2, "是的，只有完全重合的拓扑才会挂接。"),
  ];

  const p = writeFixture(entries);
  const byUuid = indexByUuid(entries);
  const { resolveOwner } = makeTurnOwnership(byUuid);

  check("Compact 内的最终答复归属于 Turn 1", resolveOwner(aFinal) === q1, resolveOwner(aFinal));
  check("Turn 2 的 parentTurn 归属于 Turn 1", resolveOwner(q2) === q2);

  const parsed = parseCliSessionJsonl(p);
  check("解析出正好 2 个有效 Turn（无伪 Turn 节点）", parsed?.turns.length === 2, parsed?.turns.length);

  const turn1 = parsed?.turns.find((t) => t.id === q1);
  const turn2 = parsed?.turns.find((t) => t.id === q2);

  check("Turn 1 包含工具调用记录", (turn1?.toolCalls.length ?? 0) === 1);
  check("Turn 1 成功保留 Compact 后的最终文本回复", Boolean(turn1?.response.includes("路网车信数据主要分为两个层级")), turn1?.response);
  check("Turn 2 的 parentId 正确指向 Turn 1（拓扑不裂成根）", turn2?.parentId === q1, turn2?.parentId);

  const rawLines = readJsonlLines(p)!;
  const tail1 = terminalAssistantLine(rawLines, q1);
  check("Turn 1 截前缀 tail 正确指向 Compact 后的 aFinal", tail1?.entry.uuid === aFinal, tail1?.entry.uuid);
}

// ── 5. import ↔ fork 边界一致（真语料全扫）─────────────────────────────────
// 这是本 harness 的主断言：import 造出来的每个 turn，fork 都必须能在**同一条**
// turn 上找到 tail。两边判据一分家这里立刻红。
{
  section("import ↔ fork 边界一致（真语料）");

  const root = path.join(os.homedir(), ".claude", "projects");
  if (!fs.existsSync(root)) {
    console.log("  ⊘ ~/.claude/projects 不存在，跳过真语料扫描（合成断言已覆盖判据本身）");
  } else {
    const files: string[] = [];
    for (const d of fs.readdirSync(root)) {
      const dir = path.join(root, d);
      let st: fs.Stats;
      try {
        st = fs.statSync(dir);
      } catch {
        continue;
      }
      if (!st.isDirectory()) continue;
      for (const f of fs.readdirSync(dir)) {
        if (f.endsWith(".jsonl")) files.push(path.join(dir, f));
      }
    }

    let turns = 0;
    let noTail = 0;
    let wrongTurn = 0;
    const badSamples: string[] = [];

    for (const f of files) {
      const parsed = parseCliSessionJsonl(f);
      if (!parsed || parsed.turns.length === 0) continue;
      const rawLines = readJsonlLines(f);
      if (!rawLines) continue;

      for (const t of parsed.turns) {
        // 只看「有回答、UI 上看得见」的 turn —— 那些才是用户能点分叉的。
        if (!t.response.trim()) continue;
        turns++;
        const tail = terminalAssistantLine(rawLines, t.id);
        if (!tail) {
          noTail++;
          if (badSamples.length < 3) {
            badSamples.push(`${path.basename(f)} turn=${t.id.slice(0, 8)} (no tail)`);
          }
          continue;
        }
        // tail 必须真属于这个 turn —— 它的文本应当出现在 import 组装的 response 里。
        // 纯工具调用的收尾 assistant 行没有文本，跳过（无从比对，也无从出错）。
        const text = userText(tail.entry)?.trim();
        if (text && !t.response.includes(text)) {
          wrongTurn++;
          if (badSamples.length < 3) {
            badSamples.push(`${path.basename(f)} turn=${t.id.slice(0, 8)} (tail 不属于该 turn)`);
          }
        }
      }
    }

    console.log(`  · 扫了 ${files.length} 个 jsonl / ${turns} 个有回答的 turn（全量，无抽样）`);
    check("每个可见 turn 都找得到 tail", noTail === 0, noTail);
    check("每个 tail 都属于该 turn", wrongTurn === 0, wrongTurn);
    for (const s of badSamples) console.log(`      ${s}`);
  }
}

console.log(failures === 0 ? "\nALL PASS\n" : `\n${failures} FAILED\n`);
process.exit(failures === 0 ? 0 : 1);

// CLI session jsonl 的**共享**读取与 turn 归属原语（纯函数，无 DB / 无 server-only）。
//
// 存在的理由是一次真实的漂移事故：cli-import.ts（把 jsonl 解析成节点树）和
// cli-fork.ts（在某个 turn 上截前缀 jsonl 造分叉）各自抄了一份 turn-start 判据，
// 之后 import 那份在实测修 bug 时长出了 5 道结构闸（isMeta / promptSource /
// interruptedMessageId / isCompactSummary / isVisibleInTranscriptOnly），fork 那份
// 一道没跟。两边对「一个 turn 从哪开始」的答案就此分家，而 fork 的入参 turnUuid
// **正是 import 定的节点 id** —— 判据不同 = fork 在一条自己认不出的 turn 上截前缀。
//
// 2026-08-01 实测（889 个 jsonl / 1897 个有回答的 turn）：老判据下 36 个 turn
// （1.90%）根本找不到 tail（分叉静默降级成线性），另有 315 个（16.61%）选出的 tail
// 与 import 的归属不是同一条 —— 前缀被截在一个**没说完的回答**中间。
//
// 所以这两侧必须走同一份实现。执行者是编译器（两边都从这里 import），不是注释；
// 一致性由 scripts/test-cli-jsonl.ts 在真 jsonl 上回归。
import fs from "node:fs";

// ── jsonl entry 形状（只声明用到的字段，其余忽略）────────────────────────────

export type CliContentBlock = {
  type: string;
  text?: string;
  thinking?: string;
  // tool_use
  id?: string;
  name?: string;
  input?: unknown;
  // tool_result
  tool_use_id?: string;
  content?: unknown;
  is_error?: boolean;
};

export type CliUsage = {
  input_tokens?: number;
  output_tokens?: number;
  cache_read_input_tokens?: number;
  cache_creation_input_tokens?: number;
};

export type CliRawEntry = {
  type: string;
  uuid?: string;
  parentUuid?: string | null;
  isSidechain?: boolean;
  // CLI 注入标记（skill 引导语 / Stop hook 通知 / "Continue from where you
  // left off." 等）。真用户输入从不带它 —— 见 isTurnStart。
  isMeta?: boolean;
  // 这条 user 消息从哪来："typed"(键入) / "sdk" / "queued" 都是真用户；
  // "system" 是 CLI 自己投递的（task-notification）。
  promptSource?: string;
  // 用户按 Esc 打断时 CLI 补的占位消息（"[Request interrupted by user]"）。
  // 它指向被打断的那条 assistant 消息，不带 isMeta / promptSource。
  interruptedMessageId?: string;
  // /compact 之后 CLI 注入的历史摘要（"This session is being continued from…"）。
  isCompactSummary?: boolean;
  isVisibleInTranscriptOnly?: boolean;
  timestamp?: string;
  cwd?: string;
  gitBranch?: string;
  sessionId?: string;
  aiTitle?: string;
  toolUseResult?: { stderr?: string; stdout?: string } | unknown;
  message?: {
    role?: string;
    content?: string | CliContentBlock[];
    usage?: CliUsage;
  };
};

// 带原始行号的 entry —— 截前缀时要按文件顺序切，行号不能丢。
export type CliRawLine = {
  lineIndex: number;
  entry: CliRawEntry;
};

// ── 基础谓词 ────────────────────────────────────────────────────────────────

export function ms(ts: string | undefined): number {
  if (!ts) return 0;
  const t = Date.parse(ts);
  return Number.isNaN(t) ? 0 : t;
}

export function userText(e: CliRawEntry): string | null {
  const c = e.message?.content;
  if (typeof c === "string") return c;
  if (Array.isArray(c)) {
    const texts = c
      .filter((b) => b.type === "text" && typeof b.text === "string")
      .map((b) => b.text as string);
    if (texts.length) return texts.join("\n");
  }
  return null;
}

export function isToolResultEntry(e: CliRawEntry): boolean {
  const c = e.message?.content;
  return Array.isArray(c) && c.some((b) => b.type === "tool_result");
}

// CLI 注入的命令/系统行不是真用户提问 —— 过滤掉。
export function isCommandNoise(text: string): boolean {
  const t = text.trimStart();
  return (
    t.startsWith("<command-name>") ||
    t.startsWith("<command-message>") ||
    t.startsWith("<local-command-") ||
    t.startsWith("<bash-input>") ||
    t.startsWith("<bash-stdout>") ||
    t.startsWith("Caveat:")
  );
}

// 一个 turn 由「真·用户提问」开启。判定的难点全在于：CLI 会往对话流里塞一堆
// 长得和用户提问一模一样的 user 文本消息（skill 触发时的 "Base directory for
// this skill: …"、后台 agent 完成的 <task-notification>、Stop hook 的反馈、
// "Continue from where you left off."）。把它们误判成 turn-start 的后果不是多
// 一个节点那么轻——它会把**后续 assistant 的最终回复整段劫走**挂到假 turn 上，
// 真 turn 只剩工具调用、response 为空，UI 里就是一条永远「正在生成…」的僵尸。
// 本机 337 个 turn 实测：修前 45 条空 response 带工具，其中 44 条是这么来的。
//
// 判据用结构字段、不用文本前缀白名单（前缀会随 CLI 版本漂）：
//   isMeta === true          —— 83 条注入全中，257 条真用户零误杀
//   promptSource === "system" —— task-notification 专属；真用户是 typed/sdk/queued
//   interruptedMessageId      —— Esc 打断的占位消息（全库 522 条），这两个字段都没有
//   isCompactSummary / isVisibleInTranscriptOnly —— /compact 注入的历史摘要
// isCommandNoise 的文本闸留作老版本 jsonl 的兜底（那时还没有这些字段）。
export function isTurnStart(e: CliRawEntry): boolean {
  if (e.type !== "user") return false;
  if (isToolResultEntry(e)) return false;
  if (e.isMeta === true) return false;
  if (e.promptSource === "system") return false;
  if (e.interruptedMessageId !== undefined) return false;
  if (e.isCompactSummary === true) return false;
  if (e.isVisibleInTranscriptOnly === true) return false;
  const text = userText(e);
  if (!text || !text.trim()) return false;
  if (isCommandNoise(text)) return false;
  return true;
}

// 宽松判据：任何带文本的非 tool_result user 消息都能当 turn-start（含被严格
// 判据挡掉的 meta / system / 命令噪声）。只用于严格判据找不到主时的兜底。
// 绝不能放行 compact summary（那不是对话起点，否则会导致 turn-start 错配）。
export function looseTurnStart(e: CliRawEntry): boolean {
  if (e.type !== "user") return false;
  if (isToolResultEntry(e)) return false;
  if (e.isCompactSummary === true) return false;
  if (e.isVisibleInTranscriptOnly === true) return false;
  return Boolean(userText(e)?.trim());
}

// ── turn 归属 ───────────────────────────────────────────────────────────────

// byUuid 必须收**全部**带 uuid 的 entry（含 type:"system" 的 compact/边界标记）——
// CLI 在每个 turn 之间插 system 节点承载父链，过滤掉会把链打断、让每个 turn
// 变成孤根。ownerTurn 上溯时需穿过这些非对话节点继续走。
//
// 拓扑桥接（Compact Continuation 断链修复）：
// 上下文超限自动 /compact 或手工 /compact 时，CLI 会写入一条带有 parentUuid: null 的
// system 节点，紧接着一条带有 isCompactSummary: true / isVisibleInTranscriptOnly: true
// 的 user 摘要节点。因为 isCompactSummary 被 isTurnStart / looseTurnStart 排除（避免生
// 成多余伪 turn 节点），且 system 节点的 parentUuid 为 null，导致紧随其后的 assistant
// 最终答复以及 compact 之后的后续 turn 沿父链上溯到 null 被静默丢弃（UI 呈现为只有工具调用、
// response 为空的僵尸状态，且后续 turn 孤立成根）。
// 在此做拓扑桥接：若 compact 相关节点其 parentUuid 缺失或为 null，且物理序列前面存在带
// uuid 的前序 entry，则将其父节点连接到 compact 前最后一条有效的 entry，恢复完整的逻辑树链路。
export function indexByUuid(
  entries: Iterable<CliRawEntry>,
): Map<string, CliRawEntry> {
  const byUuid = new Map<string, CliRawEntry>();
  const list = Array.isArray(entries) ? entries : Array.from(entries);
  for (const e of list) if (typeof e.uuid === "string") byUuid.set(e.uuid, e);

  for (let i = 0; i < list.length; i++) {
    const e = list[i];
    if (!e || typeof e.uuid !== "string") continue;
    const isCompactRoot =
      e.isCompactSummary === true ||
      e.isVisibleInTranscriptOnly === true ||
      (e.type === "system" && (e.parentUuid === null || !e.parentUuid) && i > 0);

    if (
      isCompactRoot &&
      (e.parentUuid === null || !e.parentUuid || !byUuid.has(e.parentUuid))
    ) {
      for (let j = i - 1; j >= 0; j--) {
        const prev = list[j];
        if (prev && typeof prev.uuid === "string") {
          byUuid.set(e.uuid, { ...e, parentUuid: prev.uuid });
          break;
        }
      }
    }
  }

  return byUuid;
}

// 每条 entry 归属哪个 turn-start（沿 parentUuid 上溯到最近的 turn-start）。
// 同一套上溯按不同判据跑两遍 —— 见 makeTurnOwnership 的取舍。
export function makeOwnerResolver(
  byUuid: Map<string, CliRawEntry>,
  isStart: (e: CliRawEntry) => boolean,
) {
  const turnOf = new Map<string, string | null>();
  return function ownerTurn(uuid: string): string | null {
    const cached = turnOf.get(uuid);
    if (cached !== undefined) return cached;
    const e = byUuid.get(uuid);
    if (!e) {
      turnOf.set(uuid, null);
      return null;
    }
    // 占位防环（坏 jsonl 自指）。
    turnOf.set(uuid, null);
    let owner: string | null;
    if (isStart(e)) owner = e.uuid as string;
    else owner = e.parentUuid ? ownerTurn(e.parentUuid) : null;
    turnOf.set(uuid, owner);
    return owner;
  };
}

export type TurnOwnership = {
  // 严格优先、宽松兜底的归属解析。
  resolveOwner: (uuid: string) => string | null;
  // 被宽松判据认领出来的兜底起点（import 侧要把它们一并组装成节点）。
  fallbackStartIds: Set<string>;
};

// 兜底承载：`claude --continue` / fork 出来的 jsonl，开头可能压根没有真用户
// 提问（链头是 "Continue from where you left off." 这类 meta，甚至直接是
// assistant 片段）。严格判据下这些链上溯不到任何 turn-start，整段回复会被
// **静默丢弃** —— 本机实测 117 条消息 / 16030 字符。所以严格找不到主时退一步
// 用宽松判据认领，让内容有处可去。
//
// 次序不能反：先严格、后宽松。反过来 meta 消息就会重新抢走已经有主的 turn 的
// 文本 —— 那正是这套判据当初要修的 bug 本身。
export function makeTurnOwnership(
  byUuid: Map<string, CliRawEntry>,
): TurnOwnership {
  const strictOwner = makeOwnerResolver(byUuid, isTurnStart);
  const looseOwner = makeOwnerResolver(byUuid, looseTurnStart);
  const fallbackStartIds = new Set<string>();
  function resolveOwner(uuid: string): string | null {
    const strict = strictOwner(uuid);
    if (strict) return strict;
    const loose = looseOwner(uuid);
    if (loose) fallbackStartIds.add(loose);
    return loose;
  }
  return { resolveOwner, fallbackStartIds };
}

// ── 带行号的整文件读取（截前缀用）──────────────────────────────────────────

// 与 cli-import 的宽容读取不同：这里任何一行 JSON 坏掉就整体放弃。截前缀是要
// **原样复制**这些行去造一个新会话，读漏一行等于造出一个内容缺失的 lineage，
// 宁可不分叉（调用方降级线性 resume）也不能造错。
export function readJsonlLines(jsonlPath: string): CliRawLine[] | null {
  let raw: string;
  try {
    raw = fs.readFileSync(jsonlPath, "utf8");
  } catch {
    return null;
  }
  const out: CliRawLine[] = [];
  const lines = raw.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!line.trim()) continue;
    try {
      out.push({ lineIndex: i, entry: JSON.parse(line) as CliRawEntry });
    } catch {
      return null;
    }
  }
  return out;
}

// 某个 turn 的**末条** assistant 行 —— 前缀 jsonl 切到这里为止。
// turnId 是 import 定的节点 id（= turn-start entry 的 uuid），所以归属判据必须
// 和 import 用同一套，否则切点会落在别的 turn 里或干脆找不到。
export function terminalAssistantLine(
  rawLines: CliRawLine[],
  turnId: string,
): CliRawLine | null {
  const byUuid = indexByUuid(rawLines.map((l) => l.entry));
  const { resolveOwner } = makeTurnOwnership(byUuid);

  function depth(uuid: string): number {
    const seen = new Set<string>();
    let cur: string | null | undefined = uuid;
    let n = 0;
    while (cur && !seen.has(cur)) {
      seen.add(cur);
      n++;
      cur = byUuid.get(cur)?.parentUuid;
    }
    return n;
  }

  let best: CliRawLine | null = null;
  for (const line of rawLines) {
    const uuid = line.entry.uuid;
    if (
      typeof uuid !== "string" ||
      line.entry.type !== "assistant" ||
      line.entry.isSidechain === true ||
      resolveOwner(uuid) !== turnId
    ) {
      continue;
    }
    if (!best) {
      best = line;
      continue;
    }
    const d = depth(uuid);
    const bd = depth(best.entry.uuid as string);
    if (
      d > bd ||
      (d === bd && ms(line.entry.timestamp) > ms(best.entry.timestamp)) ||
      (d === bd &&
        ms(line.entry.timestamp) === ms(best.entry.timestamp) &&
        line.lineIndex > best.lineIndex)
    ) {
      best = line;
    }
  }
  return best;
}

// 从 tailUuid 沿 parentUuid 一路上溯收集要保留的 uuid 集合。自指/成环返回 null。
export function keepUuidChain(
  rawLines: CliRawLine[],
  tailUuid: string,
): Set<string> | null {
  const byUuid = indexByUuid(rawLines.map((l) => l.entry));
  const keep = new Set<string>();
  let cur: string | null | undefined = tailUuid;
  while (cur) {
    if (keep.has(cur)) return null;
    keep.add(cur);
    cur = byUuid.get(cur)?.parentUuid;
  }
  return keep;
}

